def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    myd = []
    opd = []
    for h in history:
        if h[0] == 'D':
            myd.append(1)
        else:
            myd.append(0)
        if h[1] == 'D':
            opd.append(1)
        else:
            opd.append(0)

    myD = sum(myd)
    oppD = sum(opd)

    if n >= 3 and oppD >= n - 1:
        return 'D'

    recent_len = n if n < 10 else 10
    oppD10 = sum(opd[n - recent_len:])
    if n >= 10 and oppD10 >= 9:
        return 'D'

    recentD = oppD10 / recent_len
    oppD_rate = oppD / n

    unpun = 0
    pun = 0
    for i in range(n - 1):
        if myd[i] == 1 and opd[i] == 0:
            if opd[i + 1] == 0:
                unpun += 1
            else:
                pun += 1

    cc = 0
    for i in range(n - 1, -1, -1):
        if myd[i] == 0 and opd[i] == 0:
            cc += 1
        else:
            break

    last_my = myd[-1]
    last_opp = opd[-1]
    forgiving = oppD * 10 <= n * 7

    if last_my == 1 and last_opp == 0:
        if forgiving and unpun > pun and unpun >= 1:
            return 'D'
        if unpun == 0 and pun == 0:
            return 'C'

    if (n >= 2 and last_my == 0 and last_opp == 0 and myd[-2] == 1 and opd[-2] == 0 and
            forgiving and unpun > pun and unpun >= 1):
        return 'D'

    if last_my == 0 and last_opp == 1:
        return 'D'

    if (n >= 25 and n <= 85 and myD == 0 and cc >= 25 and
            oppD <= max(1, n // 8)):
