def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_D = 0
    recent_D = 0
    recent_start = n - 6
    if recent_start < 0:
        recent_start = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_D += 1
            if i >= recent_start:
                recent_D += 1

    opp_C = n - opp_D

    opD_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opD_streak += 1
        else:
            break

