        elif opp_D == 2 and opp_C >= 50:
            start = 75
        elif opp_D == 3 and opp_C >= 70:
            start = 88
        elif opp_D == 4 and opp_C >= 80:
            start = 96
        if n >= start:
            if n == start:
                return 'D'
            if n == start + 1:
                return 'C'
            return 'D'

    if opp_D == 0:
        return 'C'

    if opp_C == 0:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if opp_D * 3 <= opp_C:
