        if recent_D >= 3 and opp_D * 3 <= opp_C and rng.random() < 0.10:
            return 'C'
        return 'D'

    if opp_D * 2 > opp_C:
        return 'D'

    if recent_D >= 3:
        return 'D'

    return 'C'

