    n = len(history)
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    recent_start = max(0, n - 5)
    opp_recent_d = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            opp_recent_d += 1

    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_d += 1
        else:
            break

    punish = 0
    success = 0
    unprompted = 0
    for i in range(1, n):
