def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    if n <= 2:
        if last_opp == 'D':
            return 'D'
        return 'C'

    opp_c_total = 0
    my_d_total = 0
    recent_opp_c = 0
    recent_opp_d = 0

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0

    for i in range(n):
        m, o = history[i]
        if o == 'C':
            opp_c_total += 1
            if i >= recent_start:
                recent_opp_c += 1
        else:
            if i >= recent_start:
                recent_opp_d += 1
        if m == 'D':
            my_d_total += 1

    unprov_d = 0
    punish_after_D = 0
    forgive_after_D = 0

    for i in range(1, n):
        prev_m = history[i - 1][0]
        o = history[i][1]
        if o == 'D' and prev_m == 'C':
            unprov_d += 1
        if prev_m == 'D':
            if o == 'C':
                forgive_after_D += 1
            else:
                punish_after_D += 1

    # Clearly hostile opponents: do not get sucked into cooperation.
    if opp_c_total * 4 <= n and recent_opp_c <= 2:
        return 'D'

    if recent_opp_d >= 8 and unprov_d >= 2:
        return 'D'

    if n >= 90 and recent_opp_d >= 5 and unprov_d >= 2:
        return 'D'

    # If the opponent defected while we were cooperating, punish once.
    # A tiny chance to skip punishment only against extremely soft opponents.
    if last_opp == 'D' and last_my == 'C':
        if recent_opp_c >= 9 and unprov_d <= 1 and opp_c_total * 20 >= n * 19 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Mutual defection: break cycles when the opponent looks mostly cooperative,
    # but stay hard against persistent exploiters.
    if last_opp == 'D' and last_my == 'D':
        run = 0
        for j in range(n - 1, -1, -1):
            if history[j][0] == 'D' and history[j][1] == 'D':
                run += 1
            else:
                break

        if opp_c_total * 4 <= n or recent_opp_c <= 1:
            return 'D'

        if run >= 2:
            if (opp_c_total * 3 >= n * 2 or recent_opp_c >= 7) and unprov_d <= 1:
                return 'C'
            if recent_opp_c >= 3 and rng.random() < 0.3:
                return 'C'
            return 'D'

        # run == 1
        if recent_opp_c >= 8 and opp_c_total * 4 >= n * 3 and unprov_d <= 1:
            return 'C'
        if unprov_d == 0 and recent_opp_c >= 5 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # We just defected and the opponent cooperated.
    # If they tend to forgive our defections, exploit; otherwise restore cooperation.
    if last_opp == 'C' and last_my == 'D':
        if punish_after_D == 0 and forgive_after_D == 0:
            if opp_c_total * 20 >= n * 19 and my_d_total <= 2:
                if n < 80:
                    if rng.random() < 0.25:
                        return 'D'
                elif n < 98:
                    if rng.random() < 0.2:
                        return 'D'
            return 'C'

        if forgive_after_D > punish_after_D:
            if recent_opp_c >= 6 and opp_c_total * 2 >= n:
                if rng.random() < 0.75:
                    return 'D'
            elif rng.random() < 0.45:
                return 'D'
            return 'C'

        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # A few low-risk probes against opponents that have looked purely cooperative.
    if n == 50 and opp_c_total == n and my_d_total == 0:
        if rng.random() < 0.25:
            return 'D'

    if n >= 95 and opp_c_total == n and my_d_total == 0:
        if rng.random() < 0.3:
            return 'D'

    # Remaining case is mostly both-cooperated. Use a simple Markov-model DP
    # to decide whether a safe probe is worth it or cooperation should hold.
    state_counts = [0.0, 0.0, 0.0, 0.0]
    state_coops = [0.0, 0.0, 0.0, 0.0]

    for i in range(n - 1):
        m, o = history[i]
        no = history[i + 1][1]
        s = (1 if m == 'D' else 0) * 2 + (1 if o == 'D' else 0)

        w = 1.0
        if i >= n - 7:
            w = 4.0
        elif i >= n - 17:
            w = 2.0

        state_counts[s] += w
        if no == 'C':
            state_coops[s] += w

    overall_rate = opp_c_total / float(n)
    recent_len = n if n < 10 else 10
    recent_rate = recent_opp_c / float(recent_len)
    rate = 0.6 * overall_rate + 0.4 * recent_rate

    # Priors: state 0=CC, 1=CD, 2=DC, 3=DD.
    # DC remains deliberately cautious because many nice-looking opponents punish
    # our first unprovoked defection.
    priors = [
        0.65 + 0.30 * rate,
        0.40 + 0.45 * rate,
        0.15 + 0.10 * rate,
        0.20 + 0.50 * rate
    ]

    prior_w = 2.0
    q = []

    for s in range(4):
        pv = priors[s]
        if pv < 0.0:
            pv = 0.0
        elif pv > 1.0:
            pv = 1.0

        qv = (state_coops[s] + pv * prior_w) / (state_counts[s] + prior_w)
        if qv < 0.0:
            qv = 0.0
        elif qv > 1.0:
            qv = 1.0

        q.append(qv)

    cur_s = (1 if last_my == 'D' else 0) * 2 + (1 if last_opp == 'D' else 0)
    rem = 100 - n
    v = [0.0, 0.0, 0.0, 0.0]
    choose = 'C'

    for k in range(1, rem + 1):
        if k == rem:
            qs = q[cur_s]
            val_c = qs * (3.0 + v[0]) + (1.0 - qs) * v[1]
            val_d = qs * (5.0 + v[2]) + (1.0 - qs) * (1.0 + v[3])

            if val_d > val_c + 1e-9:
                choose = 'D'
            else:
                choose = 'C'

        v0, v1, v2, v3 = v
        nv = []

        for s in range(4):
            qs = q[s]
            cval = qs * (3.0 + v0) + (1.0 - qs) * v1
            dval = qs * (5.0 + v2) + (1.0 - qs) * (1.0 + v3)

            if dval > cval + 1e-9:
                nv.append(dval)
            else:
                nv.append(cval)

        v = nv

    return choose

