def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    opp_c = 0
    for i in range(n):
        if op[i] == 'C':
            opp_c += 1

    opp_rate = opp_c / n

    recent_len = min(10, n)
    recent_opp_c = 0
    for i in range(n - recent_len, n):
        if op[i] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / recent_len

    if opp_rate < 0.25 and recent_rate < 0.35:
        return 'D'

    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    r_mix = 0.6 * opp_rate + 0.4 * recent_rate
    alpha = 1.5

    p0 = 0.35 + 0.65 * r_mix
    p1 = 0.30 + 0.70 * r_mix
    p2 = 0.02 + 0.28 * r_mix
    p3 = 0.02 + 0.25 * r_mix

    if p0 < 0.02:
        p0 = 0.02
    if p0 > 0.98:
        p0 = 0.98
    if p1 < 0.02:
        p1 = 0.02
    if p1 > 0.98:
        p1 = 0.98
    if p2 < 0.02:
        p2 = 0.02
    if p2 > 0.98:
        p2 = 0.98
    if p3 < 0.02:
        p3 = 0.02
    if p3 > 0.98:
        p3 = 0.98

    c_counts = [p0 * alpha, p1 * alpha, p2 * alpha, p3 * alpha]
    d_counts = [(1.0 - p0) * alpha, (1.0 - p1) * alpha, (1.0 - p2) * alpha, (1.0 - p3) * alpha]

    start = max(1, n - 30)
    for i in range(start, n):
        if my[i - 1] == 'C':
            idx = 0 if op[i - 1] == 'C' else 1
        else:
            idx = 2 if op[i - 1] == 'C' else 3

        if op[i] == 'C':
            c_counts[idx] += 1.0
        else:
            d_counts[idx] += 1.0

    probs = []
    for i in range(4):
        probs.append(c_counts[i] / (c_counts[i] + d_counts[i]))

    ev_start = max(1, n - 20)
    ev_forgive = 0
    ev_punish = 0
    for i in range(ev_start, n):
        if my[i - 1] == 'D' and op[i - 1] == 'C':
            if op[i] == 'C':
                ev_forgive += 1
            else:
                ev_punish += 1

    if last_my == 'D' and last_op == 'D':
        if opp_rate >= 0.55 and recent_rate >= 0.45 and run_d <= 3:
            return 'C'

    if last_my == 'D' and last_op == 'C':
        if opp_rate >= 0.45 and recent_rate >= 0.45 and ev_forgive == 0 and ev_punish == 0:
            return 'C'

    if last_my == 'C' and last_op == 'D':
        if ev_punish > 0 and opp_rate >= 0.55:
            return 'C'

    h = 100 - n

    V = [0.0, 0.0, 0.0, 0.0]
    for rem in range(1, h):
        W = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            p = probs[s]
            q = 1.0 - p
            valC = p * (3.0 + V[0]) + q * (0.0 + V[1])
            valD = p * (5.0 + V[2]) + q * (1.0 + V[3])
            W[s] = valD if valD > valC else valC
        V = W

    cur = (2 if last_my == 'D' else 0) + (0 if last_op == 'C' else 1)
    p = probs[cur]
    q = 1.0 - p

    valC = p * (3.0 + V[0]) + q * (0.0 + V[1])
    valD = p * (5.0 + V[2]) + q * (1.0 + V[3])

    if cur == 0 and h > 4 and n < 95 and valC >= valD:
        if opp_rate >= 0.7 and recent_rate >= 0.7 and run_c >= 6 and ev_forgive == 0 and ev_punish == 0:
            probe = 0.02 if opp_c == n else 0.006
            if rng.random() < probe:
                return 'D'

    return 'D' if valD > valC else 'C'

