def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    last_m, last_o = history[-1]

    unprovoked = 0
    punish = 0
    forgive = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'C':
            if co == 'D':
                unprovoked += 1
        else:
            if co == 'D':
                punish += 1
            else:
                forgive += 1

    w = 5 if n >= 5 else n
    recent_opp_d = 0
    for j in range(n - w, n):
        if history[j][1] == 'D':
            recent_opp_d += 1

    if n >= 6 and my_d * 3 <= max(1, n):
        seq = tuple(o for _, o in history[-6:])
        if (seq == ('C', 'D', 'C', 'D', 'C', 'D') or
            seq == ('D', 'C', 'D', 'C', 'D', 'C')) and 2 * n < 5 * opp_d < 3 * n:
            return 'D'

    if n < 10:
        if last_o == 'D':
            return 'D'
        return 'C'

    if recent_opp_d >= 4 or unprovoked > max(2, n // 4):
        return 'D'

    if n >= 90:
        if last_o == 'D':
            if last_m == 'C':
                return 'D'
            if recent_opp_d >= 3:
                return 'D'
            return 'C'
        if n == 98 and forgive >= 2 and punish == 0 and opp_d <= max(2, n // 20):
            return 'D'

    if last_o == 'C':
        if forgive >= 3 and punish == 0 and opp_d <= max(2, n // 8):
            if rng.random() < 0.04:
                return 'D'
        return 'C'

    if n < 30:
        if opp_d <= max(1, n // 10):
            return 'C'
        return 'D'

    if opp_d > (3 * n) // 10:
        return 'D'

    if opp_d > (3 * n) // 20:
        if last_m == 'D' and last_o == 'D' and n >= 2 and history[-2][1] == 'D':
            return 'C'
        return 'D'

    return 'C'

