    seen_my_D = 0
    opp_C_after_my_D = 0

    seen_my_C = 0
    opp_D_after_my_C = 0

    for i in range(n):
        a, b = history[i]

        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if a == 'D':
            my_d += 1

        dist = n - i
        if dist <= 5:
            if b == 'D':
                opp_def5 += 1
            if a == 'D':
                my_def5 += 1

        if dist <= 10 and b == 'D':
            opp_def10 += 1

        if i > 0:
            prev_a = history[i - 1][0]
            if prev_a == 'D':
                seen_my_D += 1
                if b == 'C':
                    opp_C_after_my_D += 1
            else:
                seen_my_C += 1
                if b == 'D':
                    opp_D_after_my_C += 1

    # Pseudo-likelihood that opponent cooperates after one of our defections.
    pC_after_D = (opp_C_after_my_D + 1.0) / (seen_my_D + 2.0)

    opp_D_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_D_streak += 1
        else:
            break

    unprov_D_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'D':
            unprov_D_streak += 1
        else:
            break

    # Classify opponent as unreliable/hostile enough to mostly defect.
    if n <= 8:
