    opp_c_rate = opp_c_total / n

    rec_len = 8 if n >= 8 else n
    op_c_rec = sum(1 for a in op[n - rec_len:] if a == 'C')
    op_c_rec_rate = op_c_rec / rec_len

    aCC = aCD = aDC = aDD = 0
    for i in range(1, n):
        prev_my = my[i - 1]
        curr_op = op[i]
        if prev_my == 'C':
            if curr_op == 'C':
                aCC += 1
            else:
                aCD += 1
        else:
            if curr_op == 'C':
                aDC += 1
            else:
                aDD += 1

    start_i = 1 if n <= 11 else n - 10
    rDC = rDD = 0
    for i in range(start_i, n):
        prev_my = my[i - 1]
        curr_op = op[i]
        if prev_my == 'D':
            if curr_op == 'C':
                rDC += 1
            else:
                rDD += 1

    d_total = aDC + aDD
    rd_total = rDC + rDD

    tolerant = False
    if rd_total >= 2:
