    d_opp = n - c_opp

    if c_opp == 0:
        return 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    if n == 99:
        return 'D'

    K = 10

    if d_opp == 0:
        if n < K:
            return 'C'

        confirm = False
        for i in range(1, n):
            if (me[i - 1] == 'D' and opp[i - 1] == 'C' and
                me[i] == 'C' and opp[i] == 'C'):
                confirm = True
                break

        if confirm:
            return 'D'
        if last_me == 'C':
            return 'D'
        return 'C'

    if d_opp * 100 >= n * 65:
        return 'D'

    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    if last_opp == 'D' and streak_d >= 3:
        return 'D'

    po = 0
    pc = 0
    uo = 0
    uc = 0
    mirror = 0

    for i in range(1, n):
        if opp[i] == me[i - 1]:
            mirror += 1

        if me[i - 1] == 'D':
            po += 1
            if opp[i] == 'D':
                pc += 1
        else:
            uo += 1
            if opp[i] == 'D':
                uc += 1

    punish_rate = pc / po if po else 0.0
    unprov_rate = uc / uo if uo else 0.0
    mirror_rate = mirror / (n - 1) if n > 1 else 0.0
    opp_def_rate = d_opp / n

    if unprov_rate > 0.45:
        return 'D'

    rec_d = sum(1 for x in opp[-10:] if x == 'D')

    reactive = (
        mirror_rate > 0.62 or
