def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
    opp_d = n - opp_c
    last_me = history[-1][0]

    t_c = 0
    c_c = 0
    t_d = 0
    c_d = 0
    rt_c = 0
    rc_c = 0
    rt_d = 0
    rc_d = 0
    recent_start = n - 21
    if recent_start < 0:
        recent_start = 0

    for i in range(n - 1):
        me = history[i][0]
        next_op = history[i + 1][1]
        coop = 1 if next_op == 'C' else 0
        recent = 1 if i >= recent_start else 0
        if me == 'C':
            t_c += 1
            c_c += coop
            if recent:
                rt_c += 1
                rc_c += coop
        else:
            t_d += 1
            c_d += coop
            if recent:
                rt_d += 1
                rc_d += coop

    base = float(opp_c) / float(n)
    if base >= 0.5:
        prior_c = 1.7
        prior_d = 0.4
    else:
        prior_c = 0.5
        prior_d = 0.2

    cnt_c = float(t_c + 2 * rt_c)
    cnt_d = float(t_d + 2 * rt_d)
    if cnt_c > 0.0:
        p_c = (float(c_c + 2 * rc_c) + prior_c) / (cnt_c + 2.0)
    else:
        p_c = prior_c / 2.0
    if cnt_d > 0.0:
        p_d = (float(c_d + 2 * rc_d) + prior_d) / (cnt_d + 2.0)
    else:
        p_d = prior_d / 2.0

    if p_c < 0.05:
        p_c = 0.05
    if p_c > 0.97:
        p_c = 0.97
    if p_d < 0.02:
        p_d = 0.02
    if p_d > 0.97:
        p_d = 0.97

    if opp_d == 0:
        if t_d == 0 and last_me == 'D':
            if n >= 95:
                return 'D'
            return 'C'
        if t_d == 0 and last_me == 'C':
            prob = 0.0
            if n >= 8:
                prob = 0.03
            if n >= 20:
                prob = 0.07
            if n >= 45:
                prob = 0.13
            if n >= 70:
                prob = 0.27
            if n >= 85:
                prob = 0.45
            if n >= 92:
                prob = 0.70
            if n >= 96:
                prob = 0.90
            if rng.random() < prob:
                return 'D'

    future = 100 - n - 1
    vc = 0.0
    vd = 0.0
    for _ in range(future):
        new_vc = 3.0 * p_c + vc
        alt_vc = 1.0 + 4.0 * p_c + vd
        if alt_vc > new_vc:
            new_vc = alt_vc

        new_vd = 3.0 * p_d + vc
        alt_vd = 1.0 + 4.0 * p_d + vd
        if alt_vd > new_vd:
            new_vd = alt_vd

        vc = new_vc
        vd = new_vd

    p_now = p_c if last_me == 'C' else p_d
    val_c = 3.0 * p_now + vc
    val_d = 1.0 + 4.0 * p_now + vd

    if val_d > val_c:
        return 'D'
    return 'C'

