def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 5:
        return 'D' if history[-1][1] == 'D' else 'C'

    opp_c = 0
    recent_opp_c = 0
    start_recent = n - 12
    if start_recent < 0:
        start_recent = 0
    for i in range(n):
        b = history[i][1]
        if b == 'C':
            opp_c += 1
            if i >= start_recent:
                recent_opp_c += 1

    if opp_c == 0:
        return 'D'
    if n >= 15 and recent_opp_c == 0 and opp_c <= 2:
        return 'D'

    nums = [0.0, 0.0, 0.0, 0.0]
    dens = [0.0, 0.0, 0.0, 0.0]
    window = 12
    for i in range(1, n):
        prev_my = history[i - 1][0]
        prev_opp = history[i - 1][1]
        idx = 0
        if prev_my == 'D':
            idx = 2
        if prev_opp == 'D':
            idx += 1
        w = 1.0 if n - i <= window else 0.15
        dens[idx] += w
        if history[i][1] == 'C':
            nums[idx] += w

    priors = [0.85, 0.70, 0.28, 0.12]
    strength = 4.0
    probs = [0.0, 0.0, 0.0, 0.0]
    for j in range(4):
        probs[j] = (nums[j] + priors[j] * strength) / (dens[j] + strength)

    last_my = history[-1][0]
    last_opp = history[-1][1]

    if last_opp == 'D' and last_my == 'C':
        recent_my_d = 0
        start_my = n - 3
        if start_my < 0:
            start_my = 0
        for k in range(start_my, n):
            if history[k][0] == 'D':
                recent_my_d += 1
        if recent_my_d == 0:
            return 'D'

    cur = 0
    if last_my == 'D':
        cur = 2
    if last_opp == 'D':
        cur += 1

    p = probs[cur]
    m = 100 - n
    v = [0.0, 0.0, 0.0, 0.0]

    for _ in range(m - 1):
        nv = [0.0, 0.0, 0.0, 0.0]
        for j in range(4):
            pj = probs[j]
            cv_j = pj * (3.0 + v[0]) + (1.0 - pj) * v[1]
            dv_j = pj * (5.0 + v[2]) + (1.0 - pj) * (1.0 + v[3])
            nv[j] = dv_j if dv_j > cv_j else cv_j
        v = nv

    cv = p * (3.0 + v[0]) + (1.0 - p) * v[1]
    dv = p * (5.0 + v[2]) + (1.0 - p) * (1.0 + v[3])

    if dv > cv + 0.05:
        return 'D'
    if cv > dv + 0.05:
        return 'C'
    return 'C'

