                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    overall_opp = opp_c / n
    r10 = min(10, n)
    recent10 = sum(1 for _, b in history[-r10:] if b == 'C') / r10
    r20 = min(20, n)
    recent20 = sum(1 for _, b in history[-r20:] if b == 'C') / r20
    score_diff = my_score - opp_score

    opp_d_streak = 0
    for _, b in reversed(history):
        if b == 'D':
            opp_d_streak += 1
        else:
