def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]
    rounds_left = 100 - n

    op_d = sum(1 for x in op if x == 'D')
    my_d = sum(1 for x in my if x == 'D')
    overall_c = (n - op_d) / n

    w = min(15, n)
    recent_c = sum(1 for x in op[-w:] if x == 'C')
    recent_d = w - recent_c
    recent_rate = recent_c / w

    c_after_c = 0
    c_after_d = 0
    tot_c = 0
    tot_d = 0

    for i in range(1, n):
        if my[i - 1] == 'C':
            tot_c += 1
            if op[i] == 'C':
                c_after_c += 1
        else:
            tot_d += 1
            if op[i] == 'C':
                c_after_d += 1

    if tot_c > 0:
        p_c = (c_after_c + 1.0) / (tot_c + 2.0)
    else:
        p_c = overall_c

    if tot_d > 0:
        p_d = (c_after_d + 1.0) / (tot_d + 2.0)
    else:
        p_d = 0.5

    p_c = min(1.0, max(0.0, p_c))
    p_d = min(1.0, max(0.0, p_d))

    if last_my == 'C':
        q = p_c
    else:
        q = p_d
    q = (2.0 * q + recent_rate + overall_c) / 4.0

    def_run = 0
    for x in reversed(op):
        if x == 'D':
            def_run += 1
        else:
            break

    coop_run = 0
    for x in reversed(op):
        if x == 'C':
            coop_run += 1
        else:
            break

    mutual_c_run = 0
    mutual_d_run = 0
    if my[-1] == op[-1]:
        if my[-1] == 'C':
            for i in range(n - 1, -1, -1):
                if my[i] == 'C' and op[i] == 'C':
                    mutual_c_run += 1
                else:
                    break
        else:
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and op[i] == 'D':
                    mutual_d_run += 1
                else:
                    break

    exploitable = (
        tot_d >= 1
        and p_d >= 0.60
        and overall_c >= 0.68
        and recent_rate >= 0.70
    )

    if n == 99:
        return 'D'

    if n == 98:
        if last_op == 'D' or overall_c < 0.55 or recent_rate < 0.55:
            return 'D'
        if exploitable:
            return 'D'
        if op_d == 0:
            if rng.random() < 0.50:
                return 'D'
            return 'C'
        threshold = p_c - (1.0 + q) / 4.0 - 0.05
        if tot_d > 0 and p_d >= threshold:
            return 'D'
        if last_my == 'D' and last_op == 'C' and p_d >= 0.60 and recent_rate >= 0.75:
            return 'D'
        return 'C'

    # Occasional test against a player that has been cooperatively flawless so far.
    if op_d == 0 and my_d == 0 and last_my == 'C' and last_op == 'C' and 84 <= n <= 92:
        if rng.random() < 0.16:
            return 'D'

    if last_op == 'D':
