def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    c_opp = 0
    d_opp = 0
    my_d = 0
    first_my_d = -1
    punish = 0
    forgive = 0
    unprov = 0
    mirror = 0
    alt = 0

    for i in range(n):
        m = history[i][0]
        o = history[i][1]

        if o == 'C':
            c_opp += 1
        else:
            d_opp += 1

        if m == 'D':
            my_d += 1
            if first_my_d < 0:
                first_my_d = i

        if i > 0:
            pm = history[i - 1][0]
            po = history[i - 1][1]

            if o != po:
                alt += 1
            if o == pm:
                mirror += 1

            if o == 'D':
                if pm == 'D':
                    punish += 1
                else:
                    unprov += 1
            else:
                if pm == 'D':
                    forgive += 1

    if n >= 99:
        return 'D'

    if d_opp == 0:
        if my_d == 0:
            if n < 5:
                return 'C'
            return 'D'
        if n == first_my_d + 1:
            return 'C'
        return 'D'

    if c_opp == 0:
        return 'D'

    last = history[n - 1][1]
    last_me = history[n - 1][0]

    if my_d == 1 and d_opp == 1 and last == 'D' and last_me == 'D':
        return 'C'

    coop_rate = c_opp / n
    if coop_rate < 0.22:
        return 'D'

    denom = n - 1
    mirror_rate = mirror / denom if denom > 0 else 0.0

    streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_d += 1
        i -= 1

    streak_start = i + 1
    provoked = streak_d > 0 and streak_start > 0 and history[streak_start - 1][0] == 'D'

    my_streak_d = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_streak_d += 1
        i -= 1

    recent_d = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_d += 1

    if last == 'D':
        max_forgive = 2 if (mirror_rate >= 0.65 and coop_rate > 0.7) else 1
        if provoked and streak_d <= max_forgive and recent_d <= max_forgive + 1:
            return 'C'
        return 'D'

    if n >= 8 and alt >= n - 2 and mirror_rate < 0.7:
        return 'D'

    if recent_d >= 3:
        return 'D'

    if last_me == 'D':
        if punish == 0 and forgive >= 1 and coop_rate > 0.65:
            return 'D'
        if punish == 0 and unprov > 0 and mirror_rate < 0.6:
            return 'D'

    remaining = 100 - n
    if remaining <= 5:
        if punish == 0 and my_d > 0 and coop_rate > 0.65:
            return 'D'
        if punish <= 1 and forgive >= 2 and mirror_rate < 0.7 and coop_rate > 0.8 and recent_d == 0:
            return 'D'

    if mirror_rate >= 0.7:
        return 'C'

    if coop_rate < 0.5:
        return 'D'

    return 'C'

