def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_d = n - opp.count('C')

    # Establish a short cooperative baseline unless the opponent has already defected.
    if n < 7 and opp_d == 0:
        return 'C'

    # One deliberate probe after seven mutually cooperative rounds.
    if n == 7 and opp_d == 0:
        return 'D'

    recent = opp[-10:] if n > 10 else opp
    recent_d = recent.count('D')

    # If opponent is already very recent-defect-heavy and not rare-defection, punish directly.
    if last_opp == 'D' and recent_d >= 8 and opp_d * 2 >= n:
        return 'D'

    # Learn transition probabilities: given previous pair, probability opponent cooperates next.
    st_num = [0.0, 0.0, 0.0, 0.0]
    st_den = [0.0, 0.0, 0.0, 0.0]
    my_num = [0.0, 0.0]
    my_den = [0.0, 0.0]
    my_den_raw = [0.0, 0.0]
    op_num = [0.0, 0.0]
    op_den = [0.0, 0.0]
    trans_num = 0.0
    trans_den = 0.0

    for i in range(1, n):
        pm = 0 if me[i - 1] == 'C' else 1
        po = 0 if opp[i - 1] == 'C' else 1
        co = 1.0 if opp[i] == 'C' else 0.0

        age = n - i
        if age <= 6:
            w = 1.0
        elif age <= 16:
            w = 0.55
        elif age <= 35:
            w = 0.30
        else:
            w = 0.15

        idx = pm * 2 + po
        st_den[idx] += w
        st_num[idx] += w * co

        my_den[pm] += w
        my_num[pm] += w * co
        my_den_raw[pm] += 1.0

        op_den[po] += w
        op_num[po] += w * co

        trans_den += w
        trans_num += w * co

    recent12 = opp[-12:] if n > 12 else opp
    recent_c_rate = recent12.count('C') / float(max(1, len(recent12)))

    if trans_den > 0.0:
        trans_rate = trans_num / trans_den
        overall_prior = 0.55 * trans_rate + 0.45 * recent_c_rate
    else:
        overall_prior = 0.78 if last_opp == 'C' else 0.22

    if my_den[0] > 0.0:
        qC = (my_num[0] + 1.5 * overall_prior) / (my_den[0] + 1.5)
    else:
        qC = overall_prior

    if my_den[1] > 0.0:
        if my_den[1] < 0.75:
            priorD = overall_prior if overall_prior < 0.42 else 0.42
        else:
            priorD = overall_prior if overall_prior < 0.62 else 0.62
        qD = (my_num[1] + 1.5 * priorD) / (my_den[1] + 1.5)
    else:
        qD = overall_prior if overall_prior < 0.40 else 0.40

    if op_den[0] > 0.0:
        rC = (op_num[0] + 1.5 * overall_prior) / (op_den[0] + 1.5)
    else:
        rC = overall_prior

    if op_den[1] > 0.0:
        rD = (op_num[1] + 1.5 * overall_prior) / (op_den[1] + 1.5)
    else:
        rD = overall_prior if overall_prior < 0.55 else 0.55

    p_states = []
    for idx in range(4):
        pm = idx // 2
        po = idx % 2
        q = qC if pm == 0 else qD
        r = rC if po == 0 else rD
        marginal = 0.48 * q + 0.32 * r + 0.20 * overall_prior

        # Be skeptical about our own defect until we have observed at least one response.
        if pm == 1 and my_den_raw[1] < 1.0:
            marginal = marginal if marginal < 0.50 else 0.50

        if st_den[idx] > 0.0:
            p = (st_num[idx] + 1.5 * marginal) / (st_den[idx] + 1.5)
        else:
            p = marginal

        if p < 0.0:
            p = 0.0
        elif p > 1.0:
            p = 1.0
        p_states.append(p)

    # If we just defected and have no observed response to any D, test cautiously with one C.
    if last_me == 'D' and last_opp == 'C' and my_den_raw[1] < 1.0:
        return 'C'

    rem = 100 - n
    future = [0.0, 0.0, 0.0, 0.0]

    # Finite-horizon DP over four Markov states:
    # 0: previous (C,C), 1: previous (C,D), 2: previous (D,C), 3: previous (D,D).
    # Action index 0=C, 1=D. Next state is (chosen_action, current_opp_action).
    for _ in range(rem - 1):
        cur = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            p = p_states[s]
            np = 1.0 - p

            c_val = 3.0 * p + p * future[0] + np * future[1]
            d_val = 1.0 + 4.0 * p + p * future[2] + np * future[3]

            if c_val > d_val:
                cur[s] = c_val
            else:
                cur[s] = d_val

        future = cur

    idx = (0 if last_me == 'C' else 1) * 2 + (0 if last_opp == 'C' else 1)
    p = p_states[idx]
    np = 1.0 - p

    c_score = 3.0 * p + p * future[0] + np * future[1]
    d_score = 1.0 + 4.0 * p + p * future[2] + np * future[3]

    if d_score > c_score + 0.02:
        action = 'D'
    else:
        action = 'C'

    # Against mostly cooperative opponents, do not over-retaliate after a single punishment.
    if last_opp == 'D' and last_me == 'C':
        if opp_d <= max(2, n // 10) and recent_d <= 2 and qC > 0.50:
            return 'C'

    # Break mutual-defection spirals when opponent still responds well to cooperation.
    if action == 'D' and last_opp == 'D' and last_me == 'D':
        run_dd = 0
        for m, o in reversed(history):
            if m == 'D' and o == 'D':
                run_dd += 1
            else:
                break

        if run_dd >= 2 and opp_d < int(n * 0.65) and qC > 0.35:
            if rng.random() < 0.28:
                return 'C'

    # If the DP is very close and opponent is cooperative, allow a little stochastic probing.
    if action == 'C' and last_opp == 'C' and last_me == 'C':
        run_c = 0
        for o in reversed(opp):
            if o == 'C':
                run_c += 1
            else:
                break

        if run_c >= 14 and n >= 28 and recent_d <= 1:
            if rng.random() < 0.08:
                return 'D'

    return action

