def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1

    last_m, last_o = history[-1]

    if n < 10:
        if last_o == 'D':
            return 'D'
        return 'C'

    if opp_c == 0:
        return 'D'

    recent10 = history[-10:]
    recent10_c = sum(1 for _, o in recent10 if o == 'C')
    rec10 = recent10_c / 10.0

    recent20 = history[-20:]
    recent20_c = sum(1 for _, o in recent20 if o == 'C')
    rec20 = recent20_c / float(len(recent20)) if recent20 else rec10

    base = opp_c / float(n)
    blend = 0.45 * base + 0.35 * rec10 + 0.20 * rec20

    if base < 0.20:
        return 'D'
    if recent10_c <= 1:
        return 'D'

    cnt = [[0, 0], [0, 0], [0, 0], [0, 0]]
    for i in range(n - 1):
        m, o = history[i]
        s = (1 if m == 'D' else 0) * 2 + (1 if o == 'D' else 0)
        if history[i + 1][1] == 'C':
            cnt[s][0] += 1
        else:
            cnt[s][1] += 1

    dc_c = cnt[2][0]
    dc_d = cnt[2][1]
    dc_samples = dc_c + dc_d

    code = (1 if last_m == 'D' else 0) * 2 + (1 if last_o == 'D' else 0)

    if code == 2 and dc_samples == 0:
        return 'C'

    recent5 = history[-5:]
    recent_my_def = sum(1 for m, _ in recent5 if m == 'D')
    recent_opp_def5 = sum(1 for _, o in recent5 if o == 'D')

    streak_D = 0
    if last_o == 'D':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak_D += 1
            else:
                break

    if last_o == 'D':
        if recent_my_def == 0:
            return 'D'
        if base < 0.35 or recent_opp_def5 >= 4:
            return 'D'
        if streak_D >= 2 and n >= 75:
            return 'D'

    if opp_d == 0 and dc_c > 0 and last_o == 'C':
        return 'D'

    if dc_c >= 2 and dc_c > dc_d and last_o == 'C' and rec10 >= 0.90 and recent_opp_def5 == 0 and n < 95:
        return 'D'

    same_opp_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            same_opp_c += 1
        else:
            break

    if code == 0 and dc_samples == 0 and opp_d <= 2 and same_opp_c >= 5 and blend > 0.85:
        if n < 40:
            prob = 0.07
        elif n < 60:
            prob = 0.15
        elif n < 80:
            prob = 0.30
        else:
            prob = 0.60
        if rng.random() < prob:
            return 'D'

    p0 = max(0.40, min(0.95, 0.35 + 0.62 * blend))
    p1 = max(0.35, min(0.92, 0.30 + 0.65 * blend))
    p2 = max(0.10, min(0.38, 0.10 + 0.25 * blend))
    p3 = max(0.25, min(0.80, 0.22 + 0.60 * blend))

    priors = [p0, p1, p2, p3]
    P = []
    w = 0.8
    for s in range(4):
        c_count = cnt[s][0]
        d_count = cnt[s][1]
        p = (c_count + w * priors[s]) / (c_count + d_count + w)
        P.append(p)

    R = 100 - n
    v = [0.0, 0.0, 0.0, 0.0]

    for _ in range(R - 1):
        p = P[0]
        nv0 = p * (3.0 + v[0]) + (1.0 - p) * v[1]
        nd0 = p * (5.0 + v[2]) + (1.0 - p) * (1.0 + v[3])
        if nd0 > nv0:
            nv0 = nd0

        p = P[1]
        nv1 = p * (3.0 + v[0]) + (1.0 - p) * v[1]
        nd1 = p * (5.0 + v[2]) + (1.0 - p) * (1.0 + v[3])
        if nd1 > nv1:
            nv1 = nd1

        p = P[2]
        nv2 = p * (3.0 + v[0]) + (1.0 - p) * v[1]
        nd2 = p * (5.0 + v[2]) + (1.0 - p) * (1.0 + v[3])
        if nd2 > nv2:
            nv2 = nd2

        p = P[3]
        nv3 = p * (3.0 + v[0]) + (1.0 - p) * v[1]
        nd3 = p * (5.0 + v[2]) + (1.0 - p) * (1.0 + v[3])
        if nd3 > nv3:
            nv3 = nd3

        v = [nv0, nv1, nv2, nv3]

    p = P[code]
    c_val = p * (3.0 + v[0]) + (1.0 - p) * v[1]
    d_val = p * (5.0 + v[2]) + (1.0 - p) * (1.0 + v[3])

    if d_val > c_val + 1e-9:
        return 'D'
    return 'C'

