    d = [0.0] * 4
    start = n - 30
    if start < 0:
        start = 0

    for i in range(n - 1):
        x = me[i]
        y = op[i]
        if x == 'C':
            s = 0 if y == 'C' else 1
        else:
            s = 2 if y == 'C' else 3
        w = 3.0 if i >= start else 1.0
        if op[i + 1] == 'C':
            c[s] += w
        else:
            d[s] += w

    base = (2.0 * rate + recent_rate) / 3.0
    if base < 0.02:
        base = 0.02
    if base > 0.98:
        base = 0.98

    prior = [base, base * 0.25 + 0.02, 0.02, 0.02]
    if prior[1] < 0.02:
        prior[1] = 0.02
    if prior[1] > 0.90:
        prior[1] = 0.90

    prob = [0.0] * 4
