        tc = c[s]
        td = d[s]
        if tc + td < 0.5:
            prob[s] = prior[s]
        else:
            prob[s] = (tc + 0.3 * prior[s]) / (tc + td + 0.3)
        if prob[s] < 0.0:
            prob[s] = 0.0
        if prob[s] > 1.0:
            prob[s] = 1.0

    total_d_counts = c[2] + d[2]
    if cur == 0 and base > 0.55 and total_d_counts < 3.0 and (100 - n) > 10:
        if rng.random() < 0.04:
            return 'D'

    rem = 100 - n
    v = [0.0] * 4

    for r in range(1, rem):
        nv = [0.0] * 4
        for s in range(4):
            p = prob[s]
            vc = 3.0 * p + p * v[0] + (1.0 - p) * v[1]
            vd = 5.0 * p + 1.0 * (1.0 - p) + p * v[2] + (1.0 - p) * v[3]
            nv[s] = vc if vc >= vd else vd
