def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    if n >= 2:
        if my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'
    opD = op.count('D')
    opC = n - opD
    myD = my.count('D')
    if n < 4:
        if opD == 0:
            return 'C'
        if opD == n:
            return 'D'
        return 'C'
    opp_last = op[-1]
    if opp_last == 'D':
        if opD >= 3 and op[-2] == 'D' and op[-3] == 'D':
            return 'D'
        return 'D'
    if opD >= 4 and n >= 8:
        if myD > opD + 2:
            return 'C'
    if opC >= 3 and op[-1] == 'C' and op[-2] == 'C' and op[-3] == 'C':
        return 'C'
    if opD == 1 and n >= 6:
        return 'C'
    return 'C'
