def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = []
    op = []
    for h in history:
        my.append(h[0])
        op.append(h[1])

    last_my = my[-1]
    last_op = op[-1]

    opD = 0
    myD = 0
    for i in range(n):
        if op[i] == 'D':
            opD += 1
        if my[i] == 'D':
            myD += 1

    opC = n - opD

    if n >= 10:
        recent = op[-10:]
    else:
        recent = op

    rl = len(recent)
    rd = 0
    rc = 0
    for x in recent:
        if x == 'D':
            rd += 1
        else:
            rc += 1

    if n >= 5:
        recent5 = op[-5:]
    else:
        recent5 = op

    r5D = 0
    r5C = 0
    for x in recent5:
        if x == 'D':
            r5D += 1
        else:
            r5C += 1

    afterD_total = 0
    afterD_pun = 0
    afterC_total = 0
    afterC_pun = 0

    for i in range(n - 1):
        if my[i] == 'D':
            afterD_total += 1
            if op[i + 1] == 'D':
                afterD_pun += 1
        else:
            afterC_total += 1
            if op[i + 1] == 'D':
                afterC_pun += 1

    streak = 0
    i = n - 1
    while i >= 0:
        if my[i] == 'D' and op[i] == 'D':
            streak += 1
            i -= 1
        else:
            break

    remaining = 100 - n

    pure_d = opC == 0
    very_d = n >= 4 and rd >= 3 and rd * 2 >= rl
    heavy_d = n >= 8 and opD * 2 >= n

    c_high = afterC_total >= 3 and afterC_pun * 2 >= afterC_total
    c_low = afterC_total >= 1 and afterC_pun == 0

    d_forgive_always = afterD_total >= 1 and afterD_pun == 0
    d_forgive_good = afterD_total >= 2 and afterD_pun * 3 <= afterD_total
    d_forgive_ok = afterD_total >= 1 and afterD_pun * 2 <= afterD_total
    d_punish_often = afterD_total >= 1 and afterD_pun * 2 >= afterD_total

    d_not_worse = (
        afterD_total >= 3
