    coops = n - defects

    if coops == 0:
        return 'D'

    recent_len = min(10, n)
    recent_def = sum(1 for _, opp in history[-recent_len:] if opp == 'D')

    if defects <= 1 and recent_def == 0:
        if n < 15:
            return 'C'
        if n == 15:
            return 'D'
        if n == 16:
            return 'C'
