def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    own = []
    opp = []
    opp_D = 0
    opp_C = 0
    bad = 0

    for i in range(n):
        o, p = history[i]
        own.append(o)
        opp.append(p)

        if p == 'D':
            opp_D += 1
            if i == 0 or own[i - 1] == 'C':
                bad += 1
        else:
            opp_C += 1

    if opp_D == 0:
        return 'D' if n >= 8 else 'C'

    if opp_C == 0:
        return 'D'

    d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            d_streak += 1
        else:
            break

    start = 0
    if n >= 10:
        start = n - 10

    recent_D = 0
    recent_bad = 0
    for i in range(start, n):
        if opp[i] == 'D':
            recent_D += 1
            if i == 0 or own[i - 1] == 'C':
                recent_bad += 1

    last_opp = opp[-1]
    last_own = own[-1]

    if bad == 0:
        return 'C'

    if last_opp == 'D':
        if recent_bad >= 2 or d_streak >= 3 or bad >= 5 or recent_D >= 5 or opp_D * 2 > n:
