    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_opp = op[-1]
    rem = 100 - n

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    overall = opp_c / n

    r20 = min(20, n)
    recent20_c = 0
    for x in op[-r20:]:
        if x == 'C':
            recent20_c += 1
    recent20 = recent20_c / r20

    r5 = min(5, n)
    recent5_c = 0
    for x in op[-r5:]:
        if x == 'C':
            recent5_c += 1
    recent5 = recent5_c / r5

    d_run = 0
    for x in reversed(op):
        if x == 'D':
            d_run += 1
        else:
            break

    c_run = 0
    for x in reversed(op):
        if x == 'C':
            c_run += 1
        else:
            break

    base = 0.50 * overall + 0.35 * recent20 + 0.15 * recent5
    if d_run >= 3 and base > 0.60:
        base = 0.60
    if d_run >= 5 and base > 0.45:
        base = 0.45
    if d_run >= 8 and base > 0.30:
        base = 0.30
    if base < 0.0:
        base = 0.0
    if base > 1.0:
        base = 1.0

    cnt = [0, 0, 0, 0]
    cc = [0, 0, 0, 0]

    cnt_myC = 0
    c_myC = 0
    cnt_myD = 0
    c_myD = 0
    cnt_oppC = 0
    c_oppC = 0
    cnt_oppD = 0
    c_oppD = 0

    for i in range(1, n):
        pm = my[i - 1]
        po = op[i - 1]
        no = op[i]
        s = (2 if pm == 'D' else 0) + (1 if po == 'D' else 0)
        cnt[s] += 1
        if no == 'C':
            cc[s] += 1

        if pm == 'C':
            cnt_myC += 1
            if no == 'C':
                c_myC += 1
        else:
            cnt_myD += 1
            if no == 'C':
                c_myD += 1

        if po == 'C':
            cnt_oppC += 1
            if no == 'C':
                c_oppC += 1
        else:
            cnt_oppD += 1
            if no == 'C':
                c_oppD += 1

    if cnt_myC:
        rate_myC = c_myC / cnt_myC
    else:
        rate_myC = 0.15 + 0.80 * base

    if cnt_myD:
        rate_myD = c_myD / cnt_myD
    else:
        rate_myD = 0.03 + 0.12 * base

    if cnt_oppC:
        rate_oppC = c_oppC / cnt_oppC
    else:
        rate_oppC = 0.10 + 0.85 * base

    if cnt_oppD:
        rate_oppD = c_oppD / cnt_oppD
    else:
        rate_oppD = 0.10 + 0.70 * base

    prob = []
    for s in range(4):
        if s == 0:
            prior = 0.30 * base + 0.35 * rate_myC + 0.35 * rate_oppC
        elif s == 1:
            prior = 0.25 * base + 0.40 * rate_myC + 0.35 * rate_oppD
        elif s == 2:
            prior = 0.08 * base + 0.78 * rate_myD + 0.14 * rate_oppC
        else:
            prior = 0.10 * base + 0.60 * rate_myD + 0.30 * rate_oppD

        if prior < 0.03:
            prior = 0.03
        if prior > 0.97:
            prior = 0.97

        total = cnt[s]
        direct = cc[s]
        p = (direct + 2.5 * prior) / (total + 2.5)
        if p < 0.02:
            p = 0.02
        if p > 0.98:
            p = 0.98
        prob.append(p)

    val = [0.0, 0.0, 0.0, 0.0]
    for _ in range(1, rem):
        nv = [0.0, 0.0, 0.0, 0.0]
        for si in range(4):
            p = prob[si]
            expC = 3.0 * p + val[0] * p + val[1] * (1.0 - p)
            expD = 5.0 * p + 1.0 * (1.0 - p) + val[2] * p + val[3] * (1.0 - p)
            if expD > expC:
                nv[si] = expD
            else:
                nv[si] = expC
        val = nv

    s = (2 if last_my == 'D' else 0) + (1 if last_opp == 'D' else 0)
    p = prob[s]
    expC = 3.0 * p + val[0] * p + val[1] * (1.0 - p)
    expD = 5.0 * p + 1.0 * (1.0 - p) + val[2] * p + val[3] * (1.0 - p)

    if expD > expC:
        return 'D'
    return 'C'

