def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    if n == 99:
        return 'D'

    if n == 1 and history[0][1] == 'D':
        return 'D'

    last_me, last_op = history[-1]

    if last_me == 'C':
        cur_state = 0 if last_op == 'C' else 1
    else:
        cur_state = 2 if last_op == 'C' else 3

    den = [0, 0, 0, 0]
    num = [0, 0, 0, 0]

    op_c = 0
    me_c = 0
    probe_done = False
    all_cc = True
    recent10_op_c = 0
    recent20_op_c = 0

    for i, (a, b) in enumerate(history):
        if a == 'C':
            me_c += 1
        elif b == 'C':
            probe_done = True

        if b == 'C':
            op_c += 1

        if i >= n - 10 and b == 'C':
            recent10_op_c += 1

        if i >= n - 20 and b == 'C':
            recent20_op_c += 1

        if all_cc and (a != 'C' or b != 'C'):
            all_cc = False

        if i > 0:
            pa, pb = history[i - 1]

            if pa == 'C':
                s = 0 if pb == 'C' else 1
            else:
                s = 2 if pb == 'C' else 3

            w = 2 if i >= n - 25 else 1

            if b == 'C':
                num[s] += w
            den[s] += w

    if n == 45 and all_cc:
        return 'D'

    if n >= 90 and not probe_done:
        if last_me == 'C' and last_op == 'C' and recent10_op_c >= 9:
            if rng.random() < 0.4:
                return 'D'

    if last_me == 'D' and last_op == 'D':
        if n < 90 and (op_c > 0 or n < 25):
            if rng.random() < 0.25:
                return 'C'

    prior = [0.94, 0.55, 0.10, 0.42]
    alpha = 1.0
    p = []

    for s in range(4):
        if den[s] == 0:
            pv = prior[s]
        else:
            pv = (num[s] + alpha * prior[s]) / (den[s] + alpha)

        if pv < 0.02:
            pv = 0.02
        if pv > 0.98:
            pv = 0.98

        p.append(pv)

    rounds_left = 100 - n

    v = [0.0, 0.0, 0.0, 0.0]
    choice = 0

    for r in range(1, rounds_left + 1):
        vnext = [0.0, 0.0, 0.0, 0.0]
        choices = [1, 1, 1, 1]

        for s in range(4):
            ps = p[s]
            one = 1.0 - ps

            vC = ps * 3.0 + ps * v[0] + one * v[1]
            vD = ps * 5.0 + ps * v[2] + one * 1.0 + one * v[3]

            if vD > vC + 0.20:
                vnext[s] = vD
                choices[s] = 1
            else:
                vnext[s] = vC
                choices[s] = 0

        v = vnext

        if r == rounds_left:
            choice = choices[cur_state]

    return 'D' if choice == 1 else 'C'

