def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_op = history[-1]

    opp_c = 0
    my_c = 0
    for h in history:
        if h[0] == 'C':
            my_c += 1
        if h[1] == 'C':
            opp_c += 1

    if opp_c == 0:
        return 'D'

    if n < 8:
        if last_op == 'D':
            return 'D'
        return 'C'

    recent_len = min(10, n)
    recent_c = 0
    for h in history[n - recent_len:]:
        if h[1] == 'C':
            recent_c += 1
    recent_rate = recent_c / recent_len
    overall_rate = opp_c / n

    if recent_rate <= 0.2 and last_op == 'D':
        return 'D'
    if recent_rate <= 0.1:
        return 'D'
    if overall_rate <= 0.35 and recent_rate <= 0.45:
        return 'D'

    countC = [0.0, 0.0, 0.0, 0.0]
    countD = [0.0, 0.0, 0.0, 0.0]
    cutoff = n - 35
    for i in range(n - 1):
        me = history[i][0]
        op = history[i][1]
        if me == 'C':
            s = 0 if op == 'C' else 1
        else:
            s = 2 if op == 'C' else 3
        w = 1.0 if i >= cutoff else 0.35
        if history[i + 1][1] == 'C':
            countC[s] += w
        else:
            countD[s] += w

    forgiven = countC[2] > 0.5 and countC[2] >= countD[2]

    if opp_c == n:
        if my_c == n:
            return 'D'
        if last_op == 'C':
            if last_me == 'C':
                return 'D'
            if forgiven:
                return 'D'

    if last_me == 'C' and last_op == 'C' and recent_rate >= 0.9 and overall_rate >= 0.6:
        if countC[2] + countD[2] == 0.0 and rng.random() < 0.05:
            return 'D'

    prior = [0.85, 0.70, 0.28, 0.18]
    alpha = 2.0
    probs = [0.0, 0.0, 0.0, 0.0]
    for s in range(4):
        c = countC[s]
        d = countD[s]
        tot = c + d
        p = (c + alpha * prior[s]) / (tot + alpha)
        p += 0.07 * (recent_rate - p)
        if p < 0.02:
            p = 0.02
        elif p > 0.98:
            p = 0.98
        probs[s] = p

    if last_me == 'C':
        current_s = 0 if last_op == 'C' else 1
    else:
        current_s = 2 if last_op == 'C' else 3

    vals = [0.0, 0.0, 0.0, 0.0]
    action = ['C', 'C', 'C', 'C']
    eps = 0.02
    rem = 100 - n

    for _ in range(rem):
        new = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            pc = probs[s]
            pd = 1.0 - pc
            vC = 3.0 * pc + vals[0] * pc + vals[1] * pd
            vD = 1.0 + 4.0 * pc + vals[2] * pc + vals[3] * pd
            if vD > vC + eps:
                new[s] = vD
                action[s] = 'D'
            else:
                new[s] = vC
                action[s] = 'C'
        vals = new

    return action[current_s]

