def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    rem = 100 - n
    if rem <= 1:
        return 'D'

    my_last, opp_last = history[-1]

    my_c = 0
    opp_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1

    my_d = n - my_c

    if opp_c == 0:
        return 'D'

    if n <= 3:
        return 'D' if opp_last == 'D' else 'C'

    opp_rate = opp_c / float(n)

    run_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_c += 1
        else:
            break

    if my_d == 0 and run_c >= 4 and opp_rate > 0.88 and 45 <= n <= 85:
        if rng.random() < 0.025:
            return 'D'

    counts = [[0.0, 0.0] for _ in range(4)]
    for i in range(n - 1):
        a = history[i][0]
        b = history[i][1]
        nb = history[i + 1][1]
        s = (0 if a == 'C' else 1) * 2 + (0 if b == 'C' else 1)
        if nb == 'C':
            counts[s][0] += 1.0
        else:
            counts[s][1] += 1.0

    if opp_rate > 0.9:
        prior = [0.95, 0.35, 0.20, 0.15]
    elif opp_rate > 0.6:
        prior = [0.80, 0.30, 0.20, 0.15]
    elif opp_rate > 0.3:
        prior = [0.55, 0.25, 0.18, 0.12]
    else:
        prior = [0.25, 0.15, 0.10, 0.08]

    prob = [0.0] * 4
    for s in range(4):
        tot = counts[s][0] + counts[s][1]
        prob[s] = (counts[s][0] + prior[s]) / (tot + 1.0)
        if prob[s] < 0.0:
            prob[s] = 0.0
        elif prob[s] > 1.0:
            prob[s] = 1.0

    V = [[0.0, 0.0, 0.0, 0.0] for _ in range(rem + 1)]
    for r in range(1, rem + 1):
        prev = V[r - 1]
        cur = V[r]
        for s in range(4):
            p = prob[s]
            q = 1.0 - p
            valC = p * (3.0 + prev[0]) + q * prev[1]
            valD = p * (5.0 + prev[2]) + q * (1.0 + prev[3])
            cur[s] = valC if valC >= valD else valD

    s_cur = (0 if my_last == 'C' else 1) * 2 + (0 if opp_last == 'C' else 1)
    p = prob[s_cur]
    q = 1.0 - p
    prev = V[rem - 1]

    valC = p * (3.0 + prev[0]) + q * prev[1]
    valD = p * (5.0 + prev[2]) + q * (1.0 + prev[3])

    if valC >= valD:
        return 'C'
    return 'D'

