def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if opp_d == 0:
        if n >= 4:
            if me[-1] == 'D':
                return 'D'
            if rng.random() < 0.20:
                return 'D'
        return 'C'

    if n == 1:
        return 'D'

    recent_len = 10 if n > 10 else n
    recent_opp_c = 0
    for x in op[-recent_len:]:
        if x == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / float(recent_len)
    all_rate = opp_c / float(n)
    mixed_rate = (all_rate + recent_rate) * 0.5
    adj = 0.3 * (mixed_rate - 0.5)

    base = [[0.88 + adj, 0.60 + adj], [0.30 + adj, 0.20 + adj]]

    state_counts = [[0.0, 0.0] for _ in range(4)]
    for i in range(n - 1):
        a = 1 if me[i] == 'D' else 0
        b = 1 if op[i] == 'D' else 0
        y = 1 if op[i + 1] == 'D' else 0

        w = 1.0
        if i >= n - 5:
            w = 3.0
        elif i >= n - 15:
            w = 2.0

        idx = a * 2 + b
        state_counts[idx][y] += w

    probs = []
    alpha = 4.0
    for a in range(2):
        for b in range(2):
            c = state_counts[a * 2 + b][0]
            d = state_counts[a * 2 + b][1]
            pr = base[a][b]
            if pr < 0.05:
                pr = 0.05
            if pr > 0.95:
                pr = 0.95

            p = (c + alpha * pr) / (c + d + alpha)
            if p < 0.03:
                p = 0.03
            if p > 0.97:
                p = 0.97

            probs.append((p, 1.0 - p))

    rem = 100 - n
    v = [0.0, 0.0, 0.0, 0.0]

    for _ in range(rem - 1):
        nv = [0.0, 0.0, 0.0, 0.0]
        for idx in range(4):
            p0 = probs[idx][0]
            p1 = probs[idx][1]

            val_c = p0 * 3.0 + p0 * v[0] + p1 * v[1]
            val_d = p0 * 5.0 + p1 * 1.0 + p0 * v[2] + p1 * v[3]

            nv[idx] = val_c if val_c >= val_d else val_d
        v = nv

    last_a = 1 if me[-1] == 'D' else 0
    last_b = 1 if op[-1] == 'D' else 0
    cur = last_a * 2 + last_b

    p0 = probs[cur][0]
    p1 = probs[cur][1]

    val_c = p0 * 3.0 + p0 * v[0] + p1 * v[1]
    val_d = p0 * 5.0 + p1 * 1.0 + p0 * v[2] + p1 * v[3]

    action = 'C' if val_c >= val_d else 'D'

    if action == 'C' and last_a == 0 and last_b == 0:
        if n >= 10 and n <= 92 and mixed_rate >= 0.72:
            if rng.random() < 0.02:
                return 'D'

    return action
